package com.fintrack.khmtomnenh.productimage.controller; import com.fintrack.khmtomnenh.auth.entity.Auth; import com.fintrack.khmtomnenh.productimage.dto.ProductImageDto; import com.fintrack.khmtomnenh.productimage.entity.ProductImage; import com.fintrack.khmtomnenh.productimage.service.ProductImageService; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.http.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/products/{productId}/images") @RequiredArgsConstructor @PreAuthorize("hasRole('SUPPLIER')") public class ProductImageController {private final ProductImageService s;@GetMapping @PreAuthorize("isAuthenticated()") public List<ProductImage> list(@PathVariable Long productId){return s.list(productId);}@PostMapping public ResponseEntity<ProductImage> create(@PathVariable Long productId,@Valid @RequestBody ProductImageDto d,@AuthenticationPrincipal Auth a){return ResponseEntity.status(HttpStatus.CREATED).body(s.create(productId,d,a));}@PutMapping("/{id}") public ProductImage update(@PathVariable Long id,@Valid @RequestBody ProductImageDto d,@AuthenticationPrincipal Auth a){return s.update(id,d,a);}@DeleteMapping("/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) public void delete(@PathVariable Long id,@AuthenticationPrincipal Auth a){s.delete(id,a);}}
